import itertools
import json

def solve_puzzle():
    houses = [1, 2, 3, 4]

    # Attributes from the puzzle
    names = ["Eric", "Arnold", "Alice", "Peter"]
    styles = ["craftsman", "colonial", "ranch", "victorian"]

    solutions = []

    # Permute names across houses with constraints
    for name_perm in itertools.permutations(names):
        # Clue 1: Alice is in the second house.
        if name_perm[1] != "Alice":
            continue

        pos_name = {name: idx + 1 for idx, name in enumerate(name_perm)}

        # Clue 4: Arnold is somewhere to the right of the person in a Craftsman-style house.
        # Clue 5: The person in a Craftsman-style house is Alice -> Craftsman at house 2
        if pos_name["Arnold"] <= 2:
            continue

        # From Clue 2: Victorian is directly left of Peter -> Peter cannot be in house 1
        if pos_name["Peter"] == 1:
            continue

        # Permute styles with Craftsman fixed to house 2 (from Clue 5)
        for style_perm in itertools.permutations(styles):
            if style_perm[1] != "craftsman":
                continue

            pos_style = {style: idx + 1 for idx, style in enumerate(style_perm)}

            # Clue 2: Victorian is directly left of Peter.
            if pos_style["victorian"] + 1 != pos_name["Peter"]:
                continue

            # Clue 3: Peter is somewhere to the right of the person in a ranch-style home.
            if not (pos_name["Peter"] > pos_style["ranch"]):
                continue

            # Clue 5 already enforced by fixing craftsman at house 2 and Alice at house 2
            if pos_name["Alice"] != pos_style["craftsman"]:
                continue

            # All constraints satisfied
            solutions.append((name_perm, style_perm))

    if len(solutions) != 1:
        raise ValueError("Expected exactly one solution, found: {}".format(len(solutions)))

    name_sol, style_sol = solutions[0]

    header = ["House", "Name", "style of house"]
    rows = []
    for h in houses:
        rows.append([str(h), name_sol[h - 1], style_sol[h - 1]])

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
